// rszl.c: "RSZL" - the lighting keys the Supermarket's interior zone symbols set that the RSZ tracker (immersion.c IMM_RSZ_KEYS) does not list:
// hood light, runtime light bounce, probe blend, ambient scales, flash-light multipliers, volumetric fog-sun, ssao blur ... (rszl_keys.h, generated by
// tools/maps/gen_rszl.py from the DC render-settings modules: 183 keys of the 13 replayed region symbols, with their outdoor value = *pat-rs-pat-cloudy*
// over *pat-rs-pat* and their indoor value = *pat-rs-pat-supermarket-main-bld*). Included from immersion.c after rslog.c; ticked next to imm_rsz_tick.
//   "RSZL cam=x,y,z n=N <key> old->new ..."   every 250 ms in a match, only the keys whose live value changed (key = 'group:name' or the raw hash)
//   "RSZLFULL cam=.. part i/k <key>=live[out|in] ..."  every 20 s and at the first sample: live value with the outdoor / indoor expectation ("-" = no row)
// A garage-door walk must show these keys going out -> in over ~1 s together with sun rgbi-i 2.8 -> 0 (RSZ line). A key that stays at its outdoor value
// indoors (or vice versa) while the RSZ tonemap / sun keys move is a zone row the engine did not take. Opt-out: t2r-no-rszl.txt.
#include "rszl_keys.h"
static void ImmRszlTick(int in_match)
{
    static uint64_t at, full_at, nf_a;
    static float prev[RSZL_N];
    static int have, nf_v;
    if (!in_match) {
        have = 0;
        return;
    }
    uint64_t t = GetTickCount64();
    if (t - at < 250 || ImmNoflag("t2r-no-rszl.txt", &nf_a, &nf_v))
        return;
    at = t;
    float cp[3], cd[3];
    if (!CamPosDir(cp, cd))
        return;
    float v[RSZL_N];
    uint64_t fn = FNV64("get-render-setting-value-float");
    for (int i = 0; i < RSZL_N; i++) {
        uint64_t a = g_rszlKeys[i].id, r = DcCall(fn, 1, &a);
        uint32_t u = (uint32_t) r;
        float f;
        memcpy(&f, &u, 4);
        v[i] = r == ~0ULL ? NAN : f;
    }
    char head[96];
    snprintf(head, sizeof head, "cam=%.2f,%.2f,%.2f", (double) cp[0],
             (double) cp[1], (double) cp[2]);
    if (!have || t - full_at >= 20000) {
        full_at = t;
        const int per = 45, parts = (RSZL_N + per - 1) / per;
        for (int p = 0; p < parts; p++) {
            char line[4000];
            int q = 0;
            for (int i = p * per;
                 i < RSZL_N && i < (p + 1) * per
                 && q < (int) sizeof line - 160; i++) {
                const RszlKey *k = &g_rszlKeys[i];
                q += snprintf(line + q, sizeof line - q, " %s=%g[",
                              k->name, (double) v[i]);
                q += __builtin_isnan(k->out) ? snprintf(line + q,
                                                        sizeof line - q,
                                                        "-|") :
                    snprintf(line + q, sizeof line - q, "%g|",
                             (double) k->out);
                q += __builtin_isnan(k->in) ? snprintf(line + q,
                                                       sizeof line - q,
                                                       "-]") :
                    snprintf(line + q, sizeof line - q, "%g]",
                             (double) k->in);
            }
            Xlog("RSZLFULL %s part %d/%d%s", head, p + 1, parts, line);
        }
    }
    if (have) {
        char line[3500];
        int q = 0, nch = 0;
        for (int i = 0; i < RSZL_N && q < (int) sizeof line - 120; i++) {
            float a = prev[i], b = v[i];
            if (__builtin_isnan(a) && __builtin_isnan(b))
                continue;
            float tol = 0.002f * fabsf(a) + 1e-4f;
            if (!__builtin_isnan(a) && !__builtin_isnan(b)
                && fabsf(a - b) <= tol)
                continue;
            nch++;
            q += snprintf(line + q, sizeof line - q, " %s %g->%g",
                          g_rszlKeys[i].name, (double) a, (double) b);
        }
        if (nch)
            Xlog("RSZL %s n=%d%s", head, nch, line);
    }
    memcpy(prev, v, sizeof v);
    have = 1;
}
